fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn token(t:&mut Ptg,p:&Value)->Value{let mut out=json!({"class":t.javaClassName(),"base":t.isBaseToken()});if let Some(cls)=p["setClass"].as_i64(){out["setClass"]=call(||t.setClass(cls as u8));}if p["nullArray"]==true{if let PtgKind::Array{values,..}=&mut t.kind{*values=None;}}if p.get("field").is_some()&&matches!(t.kind,PtgKind::SxName{..}){t.setFieldName(p["field"].as_str().map(str::to_owned));t.setItemName(p["item"].as_str().map(str::to_owned));}out["ptgClass"]=json!(t.getPtgClass());out["text"]=call(||t.toString());out["rva"]=call(||t.getRVAType().to_string());out["size"]=call(||t.getSize());if matches!(t.kind,PtgKind::Array{..}){out["rows"]=json!(t.getRowCount());out["columns"]=json!(t.getColumnCount());}out}
fn record(p:&Value,data:&[u8],sv:SpreadsheetVersion)->Value{let r=FormulaRecord::new();r.setRow(-17);r.setColumn(-1);r.setXFIndex(0xabcdef01u32 as i32);r.setOptions(41);r.setValue(f64::from_bits(p["valueBits"].as_str().map(|s|u64::from_str_radix(s,16).unwrap()).unwrap_or(0x8000000000000000)));r.setFormula(if p["nullFormula"]==true{None}else{Some(Rc::new(RefCell::new(Formula::Formula(Some(Rc::new(RefCell::new(data.to_vec().into_boxed_slice()))),p["size"].as_i64().unwrap()as i32,Some(sv)))))});match p["cache"].as_str().unwrap_or(""){"empty"=>r.setCachedResultTypeEmptyString(),"string"=>r.setCachedResultTypeString(),"bool"=>r.setCachedResultBoolean(true),"error"=>r.setCachedResultErrorCode(p["error"].as_i64().unwrap_or(255)as i32),_=>{}}let text=call(||r.toString());let mut b=String::from("prefix:");let append=call(||r.appendValueText(&mut b));json!({"text":text,"append":append,"builder":b})}
